package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Complex_tan_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testTan_NaN() {
        Complex c = Complex.NaN;
        Complex result = c.tan();
        assertTrue("Result should be NaN", result.isNaN());
    }

    @Test
    public void testTan_Zero() {
        // tan(0 + 0i) = 0 + 0i
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.tan();
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_RealOnly() {
        // tan(pi/4) = 1
        Complex c = new Complex(Math.PI / 4.0, 0.0);
        Complex result = c.tan();
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_ImaginaryOnly() {
        // tan(i * 1) = i * tanh(1)
        // Using the formula: sin(2*0)/d + sinh(2*1)/d
        // d = cos(0) + cosh(2) = 1 + cosh(2)
        // real = sin(0)/d = 0
        // imag = sinh(2)/(1 + cosh(2))
        double imagVal = Math.sinh(2.0) / (1.0 + Math.cosh(2.0));
        Complex c = new Complex(0.0, 1.0);
        Complex result = c.tan();
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(imagVal, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_Complex() {
        // Test with a general complex number
        double re = 0.5;
        double im = 0.5;
        Complex c = new Complex(re, im);
        Complex result = c.tan();

        // Manual calculation for verification
        double real2 = 2.0 * re;
        double imag2 = 2.0 * im;
        double d = Math.cos(real2) + Math.cosh(imag2);
        double expectedReal = Math.sin(real2) / d;
        double expectedImag = Math.sinh(imag2) / d;

        assertEquals(expectedReal, result.getReal(), EPSILON);
        assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_LargeValues() {
        // Test behavior with large imaginary part (tanh approaches 1, so tan approaches i)
        Complex c = new Complex(0.0, 100.0);
        Complex result = c.tan();
        // tan(i*y) = i * tanh(y). As y -> inf, tanh(y) -> 1.
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(1.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_Singularity() {
        // tan(pi/2) is undefined (approaches infinity)
        // In the formula, cos(2 * pi/2) + cosh(0) = cos(pi) + 1 = -1 + 1 = 0
        Complex c = new Complex(Math.PI / 2.0, 0.0);
        Complex result = c.tan();
        // result should have infinite components or NaN depending on floating point precision
        // Given the formula: sin(pi)/0 and sinh(0)/0
        assertTrue(Double.isInfinite(result.getReal()) || Double.isNaN(result.getReal()));
    }
}
